    survey_title VARCHAR(255),
    creation_date DATE
);

CREATE TABLE Questions (
    question_id INT PRIMARY KEY,
    survey_id INT,
    question_text TEXT,
    question_type VARCHAR(50),
    is_required BOOLEAN
);

CREATE TABLE Responses (
    response_id INT PRIMARY KEY,
    question_id INT,
    participant_id INT,
    response_text TEXT,
    submission_date DATE,
    is_anonymous BOOLEAN
);

