-- Query 5: Update the total amount of a specific order after adding a new item
UPDATE Orders SET TotalAmount = (SELECT SUM(Quantity * PricePerUnit) FROM OrderItems WHERE OrderID = 104 AND IsReturned = false) WHERE OrderID = 104;

