SELECT ExhibitionName FROM Exhibitions E
JOIN (SELECT ExhibitionID, COUNT(ArtworkID) AS ArtworkCount FROM ExhibitionArtworks GROUP BY ExhibitionID) AS Counts
ON E.ExhibitionID = Counts.ExhibitionID
WHERE Counts.ArtworkCount > 20;

