-- 2. Get all grades for a student (e.g., student_id = 1) in a particular course (e.g., course_id = 1)
SELECT G.* FROM Grades G JOIN Assignments A ON G.assignment_id = A.assignment_id WHERE G.student_id = 1 AND A.course_id = 1 AND G.is_late = false;

-- 3. Insert a new grade for a student (e.g., student_id = 1) on an assignment (e.g., assignment_id = 1)
