CREATE TABLE Users (
    user_id INT PRIMARY KEY,
    username VARCHAR(50)
);

CREATE TABLE Events (
    event_id INT PRIMARY KEY,
    event_name VARCHAR(100),
    description VARCHAR(255)
);

CREATE TABLE UserEvents (
    user_event_id INT PRIMARY KEY AUTO_INCREMENT,
    user_id INT,
    event_id INT,
    event_timestamp DATETIME,
    event_data TEXT,
    is_active BOOLEAN DEFAULT true,
    FOREIGN KEY (user_id) REFERENCES Users(user_id),
    FOREIGN KEY (event_id) REFERENCES Events(event_id)
);

INSERT INTO Users (user_id, username) VALUES (1, 'Alice'), (2, 'Bob');
INSERT INTO Events (event_id, event_name, description) VALUES (101, 'Login', 'User logged in'), (102, 'Logout', 'User logged out');
INSERT INTO UserEvents (user_id, event_id, event_timestamp, event_data, is_active) VALUES (1, 101, NOW(), '{"ip": "192.168.1.1"}', true);
INSERT INTO UserEvents (user_id, event_id, event_timestamp, event_data, is_active) VALUES (1, 102, NOW(), '{"ip": "192.168.1.1"}', true);
INSERT INTO UserEvents (user_id, event_id, event_timestamp, event_data, is_active) VALUES (2, 101, NOW(), '{"ip": "10.0.0.1"}', true);
INSERT INTO UserEvents (user_id, event_id, event_timestamp, event_data, is_active) VALUES (2, 101, NOW(), '{"ip": "10.0.0.1"}', false);

-- 1. List all events performed by a specific user (e.g., user_id = 1)
SELECT E.event_name, UE.event_timestamp
FROM UserEvents UE JOIN Events E ON UE.event_id = E.event_id
WHERE UE.user_id = 1 AND UE.is_active = true;

-- 2. Find the total occurrences of a particular event (e.g., event_id = 101)
SELECT COUNT(*) FROM UserEvents WHERE event_id = 101 AND is_active = true;

-- 3. Insert a new user event
INSERT INTO UserEvents (user_id, event_id, event_timestamp, event_data, is_active) VALUES (1, 101, NOW(), '{"ip": "192.168.1.2", "device": "mobile"}', true);

-- 4. Get the top 5 most frequent events
SELECT E.event_name, COUNT(*) AS event_count
FROM UserEvents UE JOIN Events E ON UE.event_id = E.event_id
WHERE UE.is_active = true
GROUP BY E.event_name ORDER BY event_count DESC LIMIT 5;

-- 5. Count unique users who performed each event
SELECT E.event_name, COUNT(DISTINCT UE.user_id) AS unique_users
FROM UserEvents UE JOIN Events E ON UE.event_id = E.event_id
WHERE UE.is_active = true
GROUP BY E.event_name;

