    location_id INT,
    assigned_date DATE,
    is_current BOOLEAN DEFAULT true,
    PRIMARY KEY (batch_id, location_id),
    FOREIGN KEY (batch_id) REFERENCES Batches(batch_id),
    FOREIGN KEY (location_id) REFERENCES Locations(location_id)
);

