    employee_name VARCHAR(255),
    manager_id INT
);

CREATE TABLE TimeOffTypes (
    type_id INT PRIMARY KEY,
    type_name VARCHAR(255)
);

CREATE TABLE TimeOffRequests (
    request_id INT PRIMARY KEY,
    employee_id INT,
    type_id INT,
    start_date DATE,
    end_date DATE,
    status VARCHAR(50),
    approved_by_manager_id INT,
    is_approved BOOLEAN DEFAULT false
);

INSERT INTO Employees (employee_id, employee_name, manager_id) VALUES (1, 'Alice', NULL), (2, 'Bob', 1), (3, 'Charlie', 1);
INSERT INTO TimeOffTypes (type_id, type_name) VALUES (1, 'Vacation'), (2, 'Sick Leave');

-- 1. List all pending time off requests for an employee (e.g., employee_id = 2)
SELECT * FROM TimeOffRequests WHERE employee_id = 2 AND status = 'Pending';

-- 2. Find all time off requests awaiting approval from a specific manager (e.g., manager_id = 1)
SELECT * FROM TimeOffRequests WHERE approved_by_manager_id = 1 AND is_approved = false;

-- 3. Submit a new time off request (e.g., employee_id = 2, type_id = 1, dates, manager_id = 1)
