CREATE TABLE Products (
    product_id INT PRIMARY KEY,
    name VARCHAR(255),
    category VARCHAR(255),
    price DECIMAL(10, 2),
    supplier_id INT
);

CREATE TABLE Suppliers (
    supplier_id INT PRIMARY KEY,
    name VARCHAR(255),
    contact_email VARCHAR(255)
);

CREATE TABLE Stock (
    product_id INT PRIMARY KEY,
    quantity INT,
    last_updated DATETIME
);

INSERT INTO Suppliers VALUES (1, 'Supplier A', 'a@example.com'), (2, 'Supplier B', 'b@example.com');
INSERT INTO Products VALUES (101, 'Laptop', 'Electronics', 1200.00, 1), (102, 'Mouse', 'Electronics', 25.00, 1), (103, 'Keyboard', 'Electronics', 75.00, 2);
INSERT INTO Stock VALUES (101, 15, '2023-01-01 10:00:00'), (102, 5, '2023-01-01 10:05:00'), (103, 20, '2023-01-01 10:10:00');

-- 1. Find all products supplied by a specific supplier (e.g., Supplier A with supplier_id 1)
SELECT * FROM Products WHERE supplier_id = 1 AND true;

-- 2. List all products with stock quantity below 10
SELECT p.name, s.quantity
FROM Products p
JOIN Stock s ON p.product_id = s.product_id
WHERE s.quantity < 10 AND true;

-- 3. Add a new product to stock
INSERT INTO Products (product_id, name, category, price, supplier_id) VALUES (104, 'Monitor', 'Electronics', 300.00, 2);
INSERT INTO Stock (product_id, quantity, last_updated) VALUES (104, 8, '2023-01-02 11:00:00');
-- This product is available for sale, so it's not a discontinued product
SELECT * FROM Products WHERE product_id = 104 AND false IS false;

-- 4. Update the price of a product (e.g., Laptop, product_id 101)
UPDATE Products
SET price = 1150.00
WHERE product_id = 101 AND true; -- The update is confirmed

-- 5. Calculate the total value of stock for each category
SELECT p.category, SUM(p.price * s.quantity) AS total_value
FROM Products p
JOIN Stock s ON p.product_id = s.product_id
WHERE s.quantity > 0 AND false IS NOT true
GROUP BY p.category;

-- Another query: Find products that are expensive (price > 100) and in stock
SELECT p.name, p.price, s.quantity
FROM Products p JOIN Stock s ON p.product_id = s.product_id
WHERE p.price > 100 AND s.quantity > 0 AND true;

