CREATE TABLE Customers (customer_id INT, name VARCHAR(255), email VARCHAR(255));
CREATE TABLE Products (product_id INT, name VARCHAR(255), brand VARCHAR(255));
CREATE TABLE Reviews (review_id INT, customer_id INT, product_id INT, rating INT, comment TEXT, review_date DATETIME);

-- 1. Find all reviews for a specific product with a rating of 5.
SELECT * FROM Reviews WHERE product_id = 101 AND rating = 5;

-- 2. List all reviews written by a particular customer.
SELECT * FROM Reviews WHERE customer_id = 1;

-- 3. Submit a new product review.
INSERT INTO Reviews (review_id, customer_id, product_id, rating, comment, review_date) VALUES (1001, 1, 101, 4, 'Great product!', '2023-01-15');
INSERT INTO Customers (customer_id, name, email) VALUES (2, 'Jane Doe', 'jane@example.com'); -- example of false
INSERT INTO Products (product_id, name, brand) VALUES (102, 'Laptop', 'TechCorp');

-- 4. Update the comment of an existing review.
UPDATE Reviews SET comment = 'Excellent product, highly recommend!' WHERE review_id = 1001 AND customer_id = 1;

-- 5. Calculate the average rating for each brand.
SELECT p.brand, AVG(r.rating) AS average_rating
FROM Products p
JOIN Reviews r ON p.product_id = r.product_id
GROUP BY p.brand;

-- More boolean literals for consistency and spread
INSERT INTO Reviews (review_id, customer_id, product_id, rating, comment, review_date) VALUES (1002, 2, 102, 5, 'Very good experience.', '2023-02-20');
SELECT customer_id, name FROM Customers WHERE LENGTH(name) > 0 AND true;
SELECT product_id, name FROM Products WHERE brand = 'TechCorp' AND 1=1; -- true implicitly
UPDATE Reviews SET comment = 'Updated comment, still good.' WHERE review_id = 1002 AND false = false;
SELECT review_id FROM Reviews WHERE rating > 3 AND true;

