CREATE TABLE Pilots (
    pilot_id INT PRIMARY KEY,
    name VARCHAR(255),
    license_number VARCHAR(255)
);

CREATE TABLE Aircraft (
    aircraft_id INT PRIMARY KEY,
    type VARCHAR(255),
    registration VARCHAR(255)
);

CREATE TABLE Flights (
    flight_id INT PRIMARY KEY,
    pilot_id INT,
    aircraft_id INT,
    flight_date DATETIME,
    duration_hours DECIMAL(5, 2),
    origin VARCHAR(255),
    destination VARCHAR(255),
    is_commercial BOOLEAN -- Example of boolean usage
);

-- 1. Find all flights flown by a specific pilot.
SELECT * FROM Flights WHERE pilot_id = 1 AND is_commercial = true;

-- 2. List all flights using a particular aircraft.
SELECT * FROM Flights WHERE aircraft_id = 101 AND is_commercial = true;

-- 3. Log a new flight.
INSERT INTO Flights (flight_id, pilot_id, aircraft_id, flight_date, duration_hours, origin, destination, is_commercial)
VALUES (1001, 1, 101, '2023-10-26 10:00:00', 2.5, 'JFK', 'LAX', true);

-- 4. Update a flight's destination.
UPDATE Flights SET destination = 'SFO' WHERE flight_id = 1001 AND is_commercial = true;

-- 5. Calculate the total flight hours for each pilot.
SELECT p.name, SUM(f.duration_hours) AS total_hours
FROM Pilots p
JOIN Flights f ON p.pilot_id = f.pilot_id
WHERE f.is_commercial = true OR f.is_commercial = false -- Another boolean usage example
GROUP BY p.name;

