VALUES (1002, 2, 102, '2023-10-27 12:00:00', 3.0, 'LAX', 'DEN', false);

-- Yet another boolean usage in a WHERE clause for a different query type
SELECT pilot_id, COUNT(*) FROM Flights WHERE is_commercial = false GROUP BY pilot_id;

