CREATE TABLE Achievements (achievement_id INT PRIMARY KEY, game_id INT, name VARCHAR(255), description TEXT);
CREATE TABLE PlayerAchievements (player_id INT, achievement_id INT, unlock_date DATETIME, PRIMARY KEY (player_id, achievement_id));

-- 1. Find all achievements unlocked by a specific player in a game.
SELECT A.name, A.description
