CREATE TABLE Rooms (
    room_id INT PRIMARY KEY,
    room_name VARCHAR(255),
    capacity INT,
    location VARCHAR(255)
);

CREATE TABLE Equipment (
    equipment_id INT PRIMARY KEY,
    equipment_name VARCHAR(255),
    description VARCHAR(255),
    serial_number VARCHAR(255)
);

CREATE TABLE RoomEquipment (
    room_equipment_id INT PRIMARY KEY,
    room_id INT,
    equipment_id INT,
    quantity INT,
    FOREIGN KEY (room_id) REFERENCES Rooms(room_id),
    FOREIGN KEY (equipment_id) REFERENCES Equipment(equipment_id)
);

INSERT INTO Rooms VALUES (1, 'Conference Room A', 20, 'Building 1, Floor 3');
INSERT INTO Rooms VALUES (2, 'Meeting Room B', 10, 'Building 1, Floor 2');

INSERT INTO Equipment VALUES (101, 'Projector', 'HD Projector', 'SN-PJ-001');
INSERT INTO Equipment VALUES (102, 'Whiteboard', 'Magnetic Whiteboard', 'SN-WB-001');

INSERT INTO RoomEquipment VALUES (1, 1, 101, 1);
INSERT INTO RoomEquipment VALUES (2, 1, 102, 2);
INSERT INTO RoomEquipment VALUES (3, 2, 101, 1);

-- 1. List all equipment in a specific conference room (e.g., 'Conference Room A')
SELECT E.equipment_name, RE.quantity
FROM Equipment E
JOIN RoomEquipment RE ON E.equipment_id = RE.equipment_id
JOIN Rooms R ON RE.room_id = R.room_id
WHERE R.room_name = 'Conference Room A' AND true;

-- 2. Find all rooms that have a specific piece of equipment (e.g., 'Projector')
SELECT R.room_name
FROM Rooms R
JOIN RoomEquipment RE ON R.room_id = RE.room_id
JOIN Equipment E ON RE.equipment_id = E.equipment_id
WHERE E.equipment_name = 'Projector' AND true;

-- 3. Count the total quantity of each equipment type across all rooms
SELECT E.equipment_name, SUM(RE.quantity) AS total_quantity
FROM Equipment E
JOIN RoomEquipment RE ON E.equipment_id = RE.equipment_id
GROUP BY E.equipment_name
HAVING SUM(RE.quantity) > 0 AND true;

-- 4. Add a new piece of equipment (e.g., 'Monitor') to a conference room (e.g., 'Meeting Room B')
INSERT INTO Equipment (equipment_id, equipment_name, description, serial_number)
VALUES (103, 'Monitor', '27-inch LED Monitor', 'SN-MN-001');

INSERT INTO RoomEquipment (room_equipment_id, room_id, equipment_id, quantity)
SELECT 4, R.room_id, E.equipment_id, 3
FROM Rooms R, Equipment E
WHERE R.room_name = 'Meeting Room B' AND E.equipment_name = 'Monitor' AND true;

-- 5. Update the quantity of a specific equipment (e.g., 'Whiteboard') in a room (e.g., 'Conference Room A')
UPDATE RoomEquipment
SET quantity = 3
WHERE room_id = (SELECT room_id FROM Rooms WHERE room_name = 'Conference Room A' AND true)
  AND equipment_id = (SELECT equipment_id FROM Equipment WHERE equipment_name = 'Whiteboard' AND true);

