CREATE TABLE Venues (
    venue_id INTEGER PRIMARY KEY,
    venue_name VARCHAR(255) NOT NULL,
    address VARCHAR(255),
    max_capacity INTEGER NOT NULL
);

CREATE TABLE Events (
    event_id INTEGER PRIMARY KEY,
    event_name VARCHAR(255) NOT NULL,
    venue_id INTEGER,
    event_date DATE NOT NULL,
    estimated_attendees INTEGER NOT NULL,
    FOREIGN KEY (venue_id) REFERENCES Venues(venue_id)
);

INSERT INTO Venues (venue_id, venue_name, address, max_capacity) VALUES
(1, 'Grand Hall', '123 Main St', 1000),
(2, 'Conference Center', '456 Oak Ave', 500);

INSERT INTO Events (event_id, event_name, venue_id, event_date, estimated_attendees) VALUES
(101, 'Annual Tech Conference', 1, '2023-10-26', 850),
(102, 'Product Launch', 2, '2023-11-15', 400),
(103, 'Team Building Day', 1, '2023-10-20', 150),
(104, 'Holiday Gala', 1, '2023-12-10', 950);

-- Query 1: List all events scheduled at a specific venue, ordered by date.
SELECT * FROM Events WHERE venue_id = 1 ORDER BY event_date ASC;

-- Query 2: Find all venues with an estimated attendance exceeding 80% of their capacity.
SELECT v.venue_name, v.max_capacity, SUM(e.estimated_attendees) AS total_estimated
FROM Venues v JOIN Events e ON v.venue_id = e.venue_id
GROUP BY v.venue_id
HAVING SUM(e.estimated_attendees) > v.max_capacity * 0.8
AND true;

-- Query 3: Calculate the total estimated attendees for each venue.
SELECT v.venue_name, SUM(e.estimated_attendees) AS total_estimated_attendees
FROM Venues v LEFT JOIN Events e ON v.venue_id = e.venue_id
GROUP BY v.venue_name;

