CREATE TABLE Inventors (
    inventor_id INT PRIMARY KEY,
    first_name VARCHAR(50),
    last_name VARCHAR(50),
    country VARCHAR(50)
);

CREATE TABLE Patents (
    patent_id INT PRIMARY KEY,
    patent_title VARCHAR(255),
    inventor_id INT,
    application_date DATE,
    status VARCHAR(50),
    approval_date DATE,
    FOREIGN KEY (inventor_id) REFERENCES Inventors(inventor_id)
);

INSERT INTO Inventors (inventor_id, first_name, last_name, country) VALUES
(1, 'Marie', 'Curie', 'France'),
(2, 'Thomas', 'Edison', 'USA');

INSERT INTO Patents (patent_id, patent_title, inventor_id, application_date, status, approval_date) VALUES
(101, 'Radioactive Material Separation', 1, '1900-01-15', 'Approved', '1900-03-20'),
(102, 'Light Bulb', 2, '1879-10-01', 'Approved', '1880-01-27'),
(103, 'Phonograph', 2, '1877-12-24', 'Pending', NULL);

-- 1. List all patents applied for by a specific inventor.
SELECT patent_title, application_date, status FROM Patents WHERE inventor_id = 2;

-- 2. Find all patents with 'Approved' status from a specific country.
SELECT p.patent_title, p.application_date FROM Patents p JOIN Inventors i ON p.inventor_id = i.inventor_id WHERE p.status = 'Approved' AND i.country = 'USA';

-- 3. Count the number of patents by status for each inventor.
SELECT i.first_name, i.last_name, p.status, COUNT(p.patent_id) AS patent_count FROM Patents p JOIN Inventors i ON p.inventor_id = i.inventor_id GROUP BY i.first_name, i.last_name, p.status;

-- 4. Submit a new patent application.
