(104, 'New Discovery', 1, '2023-01-01', 'Pending', NULL);

-- 5. Update the status of a patent application to 'Approved' and set the approval date.
UPDATE Patents SET status = 'Approved', approval_date = '2023-03-15' WHERE patent_id = 103;

