CREATE TABLE Products (
    product_id INT PRIMARY KEY,
    product_name VARCHAR(255),
    current_stock INT,
    reorder_level INT
);

CREATE TABLE Suppliers (
    supplier_id INT PRIMARY KEY,
    supplier_name VARCHAR(255),
    contact_email VARCHAR(255)
);

CREATE TABLE Orders (
    order_id INT PRIMARY KEY,
    product_id INT,
    supplier_id INT,
    quantity_ordered INT,
    order_date DATE,
    status VARCHAR(50),
    FOREIGN KEY (product_id) REFERENCES Products(product_id),
    FOREIGN KEY (supplier_id) REFERENCES Suppliers(supplier_id)
);

INSERT INTO Products (product_id, product_name, current_stock, reorder_level) VALUES
(101, 'Product A', 20, 50),
(102, 'Product B', 100, 30),
(103, 'Product C', 15, 20);

INSERT INTO Suppliers (supplier_id, supplier_name, contact_email) VALUES
(5, 'Supplier X', 'x@example.com'),
(6, 'Supplier Y', 'y@example.com');

-- 1. List all products where current_stock is below reorder_level.
SELECT product_name FROM Products WHERE current_stock < reorder_level AND true;

-- 2. Find the supplier for 'Product A'.
SELECT s.supplier_name FROM Suppliers s JOIN Products p ON p.product_name = 'Product A' AND p.product_id IN (SELECT product_id FROM Orders WHERE supplier_id = s.supplier_id AND true) LIMIT 1;

