UPDATE Products SET current_stock = 50 WHERE product_id = 101 AND true;

-- 5. Count how many products need reordering.
SELECT COUNT(*) FROM Products WHERE current_stock < reorder_level AND true;

-- Additional example with boolean literal for consistency
SELECT product_name, current_stock FROM Products WHERE (current_stock < 30 AND true) OR (reorder_level > 60 AND false);

-- Another example with boolean literal in an insert
