VALUES (2, 102, 6, 200, CURRENT_DATE, CASE WHEN (1=1 AND true) THEN 'Pending' ELSE 'Cancelled' END);

SELECT COUNT(*) FROM Products WHERE product_name IS NOT NULL AND true;

