    lot_id INT PRIMARY KEY,
    lot_name VARCHAR(255),
    capacity INT,
    location VARCHAR(255)
);

CREATE TABLE ParkingSpots (
    spot_id INT PRIMARY KEY,
    lot_id INT,
    spot_number VARCHAR(50),
    is_occupied BOOLEAN
);

CREATE TABLE Vehicles (
    vehicle_id INT PRIMARY KEY,
    license_plate VARCHAR(50),
    vehicle_type VARCHAR(50)
);

INSERT INTO ParkingLots (lot_id, lot_name, capacity, location) VALUES
(1, 'Lot A', 100, 'North'),
(2, 'Lot B', 150, 'South');

INSERT INTO ParkingSpots (spot_id, lot_id, spot_number, is_occupied) VALUES
(101, 1, 'A1', false),
(102, 1, 'A2', false),
(103, 1, 'A3', true),
(201, 2, 'B1', false),
(202, 2, 'B2', true);

INSERT INTO Vehicles (vehicle_id, license_plate, vehicle_type) VALUES
(1, 'XYZ123', 'Car'),
(2, 'ABC456', 'Truck'),
(3, 'DEF789', 'Car'),
(5, 'GHI012', 'Car');

-- Query 1: Find all 'Available' parking spots in 'Lot A'.
SELECT PS.spot_number FROM ParkingSpots PS JOIN ParkingLots PL ON PS.lot_id = PL.lot_id WHERE PL.lot_name = 'Lot A' AND PS.is_occupied = false;

-- Query 2: List all parking spots occupied by 'Car' type vehicles.
SELECT PS.spot_number FROM ParkingSpots PS JOIN Vehicles V ON PS.spot_id = V.vehicle_id WHERE V.vehicle_type = 'Car' AND PS.is_occupied = true;

-- Query 3: Mark spot_id 101 as occupied by vehicle_id 5.
UPDATE ParkingSpots SET is_occupied = true WHERE spot_id = 101;

-- Query 4: Mark spot_id 102 as vacant.
UPDATE ParkingSpots SET is_occupied = false WHERE spot_id = 102;

-- Query 5: Count the number of occupied spots in each parking lot.
SELECT PL.lot_name, COUNT(PS.spot_id) AS occupied_spots_count FROM ParkingLots PL JOIN ParkingSpots PS ON PL.lot_id = PS.lot_id WHERE PS.is_occupied = true GROUP BY PL.lot_name;

