CREATE TABLE Events (
    event_id INT PRIMARY KEY,
    name VARCHAR(255),
    event_date DATE,
    location VARCHAR(255)
);

CREATE TABLE Attendees (
    attendee_id INT PRIMARY KEY,
    first_name VARCHAR(255),
    last_name VARCHAR(255),
    email VARCHAR(255)
);

CREATE TABLE Registrations (
    registration_id INT PRIMARY KEY,
    event_id INT,
    attendee_id INT,
    registration_date DATE,
    payment_status BOOLEAN,
    FOREIGN KEY (event_id) REFERENCES Events(event_id),
    FOREIGN KEY (attendee_id) REFERENCES Attendees(attendee_id)
);

-- 1. Find all attendees registered for a specific event (e.g., event_id = 1)
SELECT A.first_name, A.last_name, A.email
FROM Attendees A
JOIN Registrations R ON A.attendee_id = R.attendee_id
WHERE R.event_id = 1;

-- 2. List events with more than 100 registered attendees
SELECT E.name, COUNT(R.attendee_id) AS total_attendees
FROM Events E
JOIN Registrations R ON E.event_id = R.event_id
GROUP BY E.event_id, E.name
HAVING COUNT(R.attendee_id) > 100;

-- 3. Calculate the total number of paid registrations for each event
SELECT E.name, COUNT(R.registration_id) AS paid_registrations
FROM Events E
JOIN Registrations R ON E.event_id = R.event_id
WHERE R.payment_status = true
GROUP BY E.event_id, E.name;

-- 4. Register a new attendee for an event (e.g., event_id = 2, new attendee)
INSERT INTO Attendees (attendee_id, first_name, last_name, email)
VALUES (101, 'Jane', 'Doe', 'jane.doe@example.com');
INSERT INTO Registrations (registration_id, event_id, attendee_id, registration_date, payment_status)
VALUES (201, 2, 101, '2023-10-27', false);

-- 5. Update the payment status for an attendee's registration (e.g., registration_id = 201)
UPDATE Registrations
SET payment_status = true
WHERE registration_id = 201 AND payment_status = false;

INSERT INTO Registrations (registration_id, event_id, attendee_id, registration_date, payment_status)
VALUES (202, 1, 1, '2023-10-26', true);
