VALUES (204, 1, 3, '2023-10-26', true);
INSERT INTO Registrations (registration_id, event_id, attendee_id, registration_date, payment_status)
VALUES (205, 1, 4, '2023-10-26', true);
INSERT INTO Registrations (registration_id, event_id, attendee_id, registration_date, payment_status)
VALUES (206, 1, 5, '2023-10-26', false);
INSERT INTO Registrations (registration_id, event_id, attendee_id, registration_date, payment_status)
VALUES (207, 1, 6, '2023-10-26', true);
SELECT * FROM Registrations WHERE payment_status = true;

