CREATE TABLE Cars (
    car_id INT PRIMARY KEY,
    make VARCHAR(50),
    model VARCHAR(50),
    year INT,
    price DECIMAL(10, 2),
    is_sold BOOLEAN
);

CREATE TABLE Customers (
    customer_id INT PRIMARY KEY,
    first_name VARCHAR(50),
    last_name VARCHAR(50),
    phone VARCHAR(20)
);

CREATE TABLE Sales (
    sale_id INT PRIMARY KEY,
    car_id INT,
    customer_id INT,
    sale_date DATE,
    final_price DECIMAL(10, 2),
    FOREIGN KEY (car_id) REFERENCES Cars(car_id),
    FOREIGN KEY (customer_id) REFERENCES Customers(customer_id)
);

INSERT INTO Cars (car_id, make, model, year, price, is_sold) VALUES
(1, 'Toyota', 'Camry', 2020, 25000.00, false),
(2, 'Honda', 'Civic', 2021, 22000.00, false),
(3, 'Toyota', 'Camry', 2019, 23000.00, true),
(4, 'Ford', 'Focus', 2018, 18000.00, false);

INSERT INTO Customers (customer_id, first_name, last_name, phone) VALUES
(101, 'John', 'Doe', '555-1234'),
(102, 'Jane', 'Smith', '555-5678');

-- 1. List all unsold cars of a specific make and model.
SELECT * FROM Cars WHERE make = 'Toyota' AND model = 'Camry' AND is_sold = false;

-- 2. Find all cars sold to a specific customer.
SELECT C.* FROM Cars C JOIN Sales S ON C.car_id = S.car_id WHERE S.customer_id = 101;

-- 3. Calculate the total revenue from sales in a given month.
SELECT SUM(final_price) FROM Sales WHERE STRFTIME('%Y-%m', sale_date) = '2023-01';

-- 4. Record a new car sale, updating the car's is_sold status.
INSERT INTO Sales (sale_id, car_id, customer_id, sale_date, final_price) VALUES
(1001, 2, 102, '2023-01-15', 21500.00);
UPDATE Cars SET is_sold = true WHERE car_id = 2;

-- 5. Update the final_price for an existing sale.
UPDATE Sales SET final_price = 22000.00 WHERE sale_id = 1001;
-- Additional usage of boolean literal for consistency
INSERT INTO Cars (car_id, make, model, year, price, is_sold) VALUES
(5, 'Nissan', 'Altima', 2022, 26000.00, false);
INSERT INTO Cars (car_id, make, model, year, price, is_sold) VALUES
(6, 'Hyundai', 'Elantra', 2023, 24000.00, false);

