CREATE TABLE Users (
    user_id INT PRIMARY KEY,
    username VARCHAR(255),
    email VARCHAR(255),
    registration_date DATE
);

CREATE TABLE Topics (
    topic_id INT PRIMARY KEY,
    title VARCHAR(255),
    creator_user_id INT,
    creation_date DATETIME,
    FOREIGN KEY (creator_user_id) REFERENCES Users(user_id)
);

CREATE TABLE Posts (
    post_id INT PRIMARY KEY,
    topic_id INT,
    user_id INT,
    content TEXT,
    post_date DATETIME,
    is_deleted BOOLEAN DEFAULT false,
    FOREIGN KEY (topic_id) REFERENCES Topics(topic_id),
    FOREIGN KEY (user_id) REFERENCES Users(user_id)
);

-- Insert sample data
INSERT INTO Users (user_id, username, email, registration_date) VALUES
(1, 'alice', 'alice@example.com', '2022-01-15'),
(2, 'bob', 'bob@example.com', '2023-03-20'),
(3, 'charlie', 'charlie@example.com', '2021-11-01');

INSERT INTO Topics (topic_id, title, creator_user_id, creation_date) VALUES
(101, 'SQL Basics', 1, '2022-02-01 10:00:00'),
(102, 'Database Design', 3, '2021-12-05 14:30:00'),
(103, 'Frontend Frameworks', 2, '2023-04-10 09:15:00');

INSERT INTO Posts (post_id, topic_id, user_id, content, post_date, is_deleted) VALUES
(1, 101, 1, 'What is a primary key?', '2022-02-01 10:15:00', false),
(2, 101, 3, 'It uniquely identifies rows.', '2022-02-01 10:30:00', false),
(3, 102, 1, 'Normalization levels?', '2022-03-10 11:00:00', false),
(4, 103, 2, 'React vs Vue.', '2023-04-10 09:30:00', false);

-- 1. Find all posts made by a specific user (e.g., user_id = 1)
SELECT * FROM Posts WHERE user_id = 1 AND is_deleted = false;

-- 2. List topics created by users registered before 2023
SELECT T.title FROM Topics T JOIN Users U ON T.creator_user_id = U.user_id WHERE U.registration_date < '2023-01-01' AND true;

-- 3. Count the number of posts in each topic
SELECT topic_id, COUNT(post_id) AS post_count FROM Posts WHERE is_deleted = false GROUP BY topic_id;

-- 4. Create a new post in an existing topic (e.g., topic_id = 101, user_id = 2)
INSERT INTO Posts (post_id, topic_id, user_id, content, post_date, is_deleted) VALUES (5, 101, 2, 'Another question on primary keys.', '2023-05-01 13:00:00', false);

-- 5. Update the content of a specific post (e.g., post_id = 2)
UPDATE Posts SET content = 'It is an attribute or a set of attributes that uniquely identifies each record in a table.', post_date = NOW() WHERE post_id = 2 AND true;

-- Example of marking a post as deleted using boolean literal
UPDATE Posts SET is_deleted = true WHERE post_id = 4 AND false = false;

