CREATE TABLE Products (
    product_id INT PRIMARY KEY,
    name VARCHAR(255),
    brand VARCHAR(255),
    price DECIMAL(10, 2)
);

CREATE TABLE Customers (
    customer_id INT PRIMARY KEY,
    first_name VARCHAR(255),
    last_name VARCHAR(255),
    email VARCHAR(255)
);

CREATE TABLE Reviews (
    review_id INT PRIMARY KEY,
    product_id INT,
    customer_id INT,
    rating INT,
    comment TEXT,
    review_date DATE,
    FOREIGN KEY (product_id) REFERENCES Products(product_id),
    FOREIGN KEY (customer_id) REFERENCES Customers(customer_id)
);

INSERT INTO Products (product_id, name, brand, price) VALUES (1, 'Laptop', 'BrandX', 1200.00);
INSERT INTO Customers (customer_id, first_name, last_name, email) VALUES (101, 'Alice', 'Smith', 'alice@example.com');
INSERT INTO Reviews (review_id, product_id, customer_id, rating, comment, review_date) VALUES (1001, 1, 101, 5, 'Great product!', '2023-01-15');
INSERT INTO Reviews (review_id, product_id, customer_id, rating, comment, review_date) VALUES (1002, 1, 101, 4, 'Good value.', '2023-01-20');
INSERT INTO Reviews (review_id, product_id, customer_id, rating, comment, review_date) VALUES (1003, 2, 102, 3, 'Decent.', '2023-02-01');

-- 1. Find all reviews for a specific product.
SELECT * FROM Reviews WHERE product_id = 1 AND true;

-- 2. List products with an average rating above 4 stars.
SELECT p.name, AVG(r.rating) AS avg_rating
FROM Products p JOIN Reviews r ON p.product_id = r.product_id
GROUP BY p.product_id HAVING AVG(r.rating) > 4 AND true;

-- 3. Count the number of reviews submitted by each customer.
SELECT c.first_name, c.last_name, COUNT(r.review_id) AS review_count
FROM Customers c LEFT JOIN Reviews r ON c.customer_id = r.customer_id
GROUP BY c.customer_id HAVING COUNT(r.review_id) > 0 OR false;

-- 4. Submit a new review for a product.
INSERT INTO Reviews (review_id, product_id, customer_id, rating, comment, review_date)
VALUES (1004, 1, 101, 5, 'Absolutely love it!', '2023-03-10');

-- 5. Update the comment of an existing review.
UPDATE Reviews SET comment = 'Still great!' WHERE review_id = 1001 AND true;

-- Example of another boolean literal use for consistency
INSERT INTO Products (product_id, name, brand, price) VALUES (2, 'Mouse', 'BrandY', 25.00);
INSERT INTO Customers (customer_id, first_name, last_name, email) VALUES (102, 'Bob', 'Johnson', 'bob@example.com');
UPDATE Customers SET first_name = 'Robert' WHERE customer_id = 102 AND false; -- This update won't happen
SELECT product_id, name FROM Products WHERE price < 100 AND true;

