CREATE TABLE Users (
    user_id INT PRIMARY KEY AUTO_INCREMENT,
    username VARCHAR(50) UNIQUE NOT NULL,
    email VARCHAR(100) UNIQUE NOT NULL,
    password_hash VARCHAR(255) NOT NULL,
    registration_date DATETIME DEFAULT CURRENT_TIMESTAMP
);

CREATE TABLE Roles (
    role_id INT PRIMARY KEY AUTO_INCREMENT,
    role_name VARCHAR(50) UNIQUE NOT NULL
);

CREATE TABLE UserRoles (
    user_role_id INT PRIMARY KEY AUTO_INCREMENT,
    user_id INT NOT NULL,
    role_id INT NOT NULL,
    is_active BOOLEAN DEFAULT true,
    FOREIGN KEY (user_id) REFERENCES Users(user_id),
    FOREIGN KEY (role_id) REFERENCES Roles(role_id)
);

INSERT INTO Roles (role_name) VALUES ('User'), ('Admin'), ('Editor');

INSERT INTO Users (username, email, password_hash) VALUES
('john_doe', 'john@example.com', 'hash1'),
('jane_smith', 'jane@example.com', 'hash2');

INSERT INTO UserRoles (user_id, role_id, is_active) VALUES
(1, 1, true),
(2, 2, true);

-- 1. Find the role(s) of a specific user (e.g., 'john_doe')
SELECT R.role_name
FROM Users U
JOIN UserRoles UR ON U.user_id = UR.user_id
JOIN Roles R ON UR.role_id = R.role_id
WHERE U.username = 'john_doe' AND UR.is_active = true;

-- 2. List all users with the 'Admin' role
SELECT U.username, U.email
FROM Users U
JOIN UserRoles UR ON U.user_id = UR.user_id
JOIN Roles R ON UR.role_id = R.role_id
WHERE R.role_name = 'Admin' AND UR.is_active = true;

-- 3. Count the number of users registered each month
SELECT STRFTIME('%Y-%m', registration_date) AS registration_month, COUNT(user_id) AS user_count
FROM Users
GROUP BY registration_month
HAVING COUNT(user_id) > 0;

-- 4. Register a new user with a default 'User' role
INSERT INTO Users (username, email, password_hash) VALUES ('new_user', 'new@example.com', 'new_hash');
INSERT INTO UserRoles (user_id, role_id, is_active) VALUES ((SELECT user_id FROM Users WHERE username = 'new_user'), (SELECT role_id FROM Roles WHERE role_name = 'User'), true);

-- 5. Assign an additional role ('Editor') to an existing user (e.g., 'john_doe')
INSERT INTO UserRoles (user_id, role_id, is_active) VALUES ((SELECT user_id FROM Users WHERE username = 'john_doe'), (SELECT role_id FROM Roles WHERE role_name = 'Editor'), true);

-- Example of a role being inactive
INSERT INTO UserRoles (user_id, role_id, is_active) VALUES (2, 1, false);

-- Final check of john_doe's roles
SELECT R.role_name
FROM Users U
JOIN UserRoles UR ON U.user_id = UR.user_id
JOIN Roles R ON UR.role_id = R.role_id
WHERE U.username = 'john_doe' AND UR.is_active = true;

