CREATE TABLE Events (
    event_id INT PRIMARY KEY,
    name VARCHAR(255),
    event_date DATE,
    location VARCHAR(255)
);

CREATE TABLE Sessions (
    session_id INT PRIMARY KEY,
    event_id INT,
    title VARCHAR(255),
    speaker VARCHAR(255),
    start_time TIME,
    end_time TIME,
    FOREIGN KEY (event_id) REFERENCES Events(event_id)
);

CREATE TABLE Attendees (
    attendee_id INT PRIMARY KEY,
    first_name VARCHAR(255),
    last_name VARCHAR(255),
    email VARCHAR(255)
);

CREATE TABLE SessionRegistrations (
    reg_id INT PRIMARY KEY,
    session_id INT,
    attendee_id INT,
    is_confirmed BOOLEAN,
    FOREIGN KEY (session_id) REFERENCES Sessions(session_id),
    FOREIGN KEY (attendee_id) REFERENCES Attendees(attendee_id)
);

-- 1. List all sessions for a specific event, ordered by start time.
SELECT * FROM Sessions WHERE event_id = 1 ORDER BY start_time;

-- 2. Find attendees registered for a session by a particular speaker.
SELECT DISTINCT A.first_name, A.last_name
FROM Attendees A
JOIN SessionRegistrations SR ON A.attendee_id = SR.attendee_id
JOIN Sessions S ON SR.session_id = S.session_id
WHERE S.speaker = 'Dr. Jane Doe' AND SR.is_confirmed = true;

-- 3. Count the number of attendees for each session.
SELECT S.title, COUNT(SR.attendee_id) AS attendee_count
FROM Sessions S
LEFT JOIN SessionRegistrations SR ON S.session_id = SR.session_id
GROUP BY S.title;

