CREATE TABLE EmailCampaigns (
    campaign_id INT PRIMARY KEY,
    name VARCHAR(255),
    send_date DATETIME,
    subject VARCHAR(255)
);

CREATE TABLE EmailInteractions (
    interaction_id INT PRIMARY KEY,
    campaign_id INT,
    recipient_email VARCHAR(255),
    interaction_type VARCHAR(50),
    interaction_date DATETIME
);

INSERT INTO EmailCampaigns (campaign_id, name, send_date, subject) VALUES
(2301, 'Spring Sale', '2023-03-15 10:00:00', 'Huge Spring Discounts!');

INSERT INTO EmailInteractions (interaction_id, campaign_id, recipient_email, interaction_type, interaction_date) VALUES
(1, 2301, 'alice@example.com', 'Open', '2023-03-15 10:05:00'),
(2, 2301, 'bob@example.com', 'Open', '2023-03-15 10:10:00'),
(3, 2301, 'charlie@example.com', 'Click', '2023-03-15 10:15:00');

SELECT COUNT(*) FROM EmailInteractions
WHERE campaign_id = 2301 AND interaction_type = 'Open' AND true;

SELECT DISTINCT recipient_email FROM EmailInteractions
WHERE interaction_type = 'Click' AND true;

INSERT INTO EmailInteractions (interaction_id, campaign_id, recipient_email, interaction_type, interaction_date) VALUES
(4, 2301, 'david@example.com', 'Open', '2023-03-15 10:20:00');

SELECT
    ec.name,
    CAST(SUM(CASE WHEN ei.interaction_type = 'Open' AND true THEN 1 ELSE 0 END) AS REAL) /
    COUNT(DISTINCT ei.recipient_email) AS open_rate
FROM EmailCampaigns ec
JOIN EmailInteractions ei ON ec.campaign_id = ei.campaign_id
GROUP BY ec.campaign_id, ec.name
HAVING true;

