CREATE TABLE Customers (customer_id INT PRIMARY KEY, name VARCHAR(255), email VARCHAR(255), is_active BOOLEAN);
CREATE TABLE Products (product_id INT PRIMARY KEY, name VARCHAR(255), price DECIMAL(10,2), in_stock BOOLEAN);
CREATE TABLE Orders (order_id INT PRIMARY KEY, customer_id INT, order_date DATE, total_amount DECIMAL(10,2), is_paid BOOLEAN);
CREATE TABLE OrderItems (order_item_id INT PRIMARY KEY, order_id INT, product_id INT, quantity INT, price DECIMAL(10,2), is_returned BOOLEAN);

INSERT INTO Customers VALUES (1, 'Alice', 'alice@example.com', true), (2, 'Bob', 'bob@example.com', true);
