SELECT DISTINCT P.name
FROM Products P
JOIN OrderItems OI ON P.product_id = OI.product_id
JOIN Orders O ON OI.order_id = O.order_id
WHERE O.customer_id = 1 AND P.in_stock = true;

SELECT C.name, SUM(O.total_amount) AS total_spent
FROM Customers C
