CREATE TABLE Hotels (hotel_id INT PRIMARY KEY, name VARCHAR(255), city VARCHAR(100));
CREATE TABLE Rooms (room_id INT PRIMARY KEY, hotel_id INT, room_number VARCHAR(10), room_type VARCHAR(50));
CREATE TABLE Amenities (amenity_id INT PRIMARY KEY, name VARCHAR(100));
CREATE TABLE RoomAmenities (room_amenity_id INT PRIMARY KEY, room_id INT, amenity_id INT);

INSERT INTO Hotels VALUES (1, 'Grand Hyatt', 'New York'), (2, 'Hilton', 'London');
INSERT INTO Rooms VALUES (101, 1, '101A', 'Standard'), (102, 1, '102B', 'Suite'), (201, 2, '201C', 'Standard');
INSERT INTO Amenities VALUES (1, 'WiFi'), (2, 'TV'), (3, 'Minibar');
INSERT INTO RoomAmenities VALUES (1, 101, 1), (2, 101, 2), (3, 102, 1), (4, 201, 3);

-- 1. List all amenities for a specific room (e.g., room_id = 101).
SELECT A.name FROM Amenities A JOIN RoomAmenities RA ON A.amenity_id = RA.amenity_id WHERE RA.room_id = 101;

-- 2. Find all rooms in a specific hotel (e.g., hotel_id = 1) that have a 'WiFi' amenity.
SELECT R.room_number FROM Rooms R JOIN RoomAmenities RA ON R.room_id = RA.room_id JOIN Amenities A ON RA.amenity_id = A.amenity_id WHERE R.hotel_id = 1 AND A.name = 'WiFi';

-- 3. Insert a new amenity for a room.
-- Assuming room_id 101, amenity_id 3 (Minibar)
INSERT INTO RoomAmenities (room_amenity_id, room_id, amenity_id) VALUES (5, 101, 3);

-- 4. Count how many rooms have each amenity.
SELECT A.name, COUNT(RA.room_id) AS room_count FROM Amenities A LEFT JOIN RoomAmenities RA ON A.amenity_id = RA.amenity_id GROUP BY A.name;

