INSERT INTO RoomAmenities (room_amenity_id, room_id, amenity_id) VALUES (5, 101, 3);

-- 4. Count how many rooms have each amenity.
SELECT A.name, COUNT(RA.room_id) AS room_count FROM Amenities A LEFT JOIN RoomAmenities RA ON A.amenity_id = RA.amenity_id GROUP BY A.name;

